' WHEN 'twice a day' THEN 'twice daily' WHEN 'twice every 24 hours || thrice daily' THEN 'twice daily||three times daily' WHEN 'up to three times a day' THEN 'up to three times daily' ELSE dosage_frequency END AS dosage_frequency FROM drug WHERE dosage_frequency <> '') GROUP BY status;


-- GROUP G5: drug.single_dose states population + dose pairs as text ('adults 10 mg || children 5 mg'); G5a needs the highest adult dose as a number of mg, G5b needs the stated text (weight-based doses)
-- TYPE: number-vs-text
-- COLUMN: drug.single_dose
-- NOTE: FORM G5a stores the highest adult dose in mg. Adult dose: a dose whose population mentions adults, or that states no population ('15 mg', '125 to 250 mg || 250 to 500 mg', 'oral 400mg||oral 800mg', '250 mg capsule||500 mg tablet||500 mg intravenous', Octreotide's doses per indication), or 'most patients'; a dose for a named group only (children, infants, dogs, geriatric patients or hepatic impairment only) is not. mcg and g are converted; a range counts at its upper end; a stated number of tablets or injections multiplies the strength ('1-2 tablets 500mg' = 1000, '30 mg 1-2 tablets' = 60, '3x100 mg' = 300); a combination product counts its first-named ingredient ('4 g piperacillin + 0.5 g tazobactam' = 4000, '500 mg + 125 mg' = 500, '1 mg norethindrone acetate and 10 mcg ethinyl estradiol' = 1); an infusion rate (mg/hour) is not a single dose. Labels with no adult dose in mg (per kg only, tablets, capsules or mL only, dose not specified) are NULL.
-- NOTE: The natural query casts because the column is text in SQLite. The judgement calls fall inside one dose range either way (e.g. 'adults 25 mg || elderly 30-50 mg' is 25 or 50: 10 to 99 mg).
-- FORM G5a: UPDATE drug SET single_dose = CASE single_dose WHEN 'adults 25 milligrams' THEN 25 WHEN 'adults 400 mcg' THEN 0.4 WHEN 'adults 4 g piperacillin + 0.5 g tazobactam' THEN 4000 WHEN 'Esophageal-gastric varices bleeding 0.025 mg/hour intravenous infusion || Prevention of pancreatic complications 0.1 mg subcutaneous injection || Gastrointestinal pancreatic endocrine tumors 0.05 mg subcutaneous injection || Acromegaly 0.05~0.1 mg subcutaneous injection' THEN 0.1 WHEN 'adults 10-40 mg once a day||cardiovascular prevention 40 mg per day||post-transplant (immunosuppressive therapy) 20 mg per day (up to 40 mg)||renal or hepatic insufficiency 10 mg per day' THEN 40 WHEN 'adults 2 mg' THEN 2 WHEN 'adults 40 mg' THEN 40 WHEN 'adults 12.5 mg (Day 1)||adults 12.5 mg twice/d (for 2 days)||adults 25 mg twice/d (for 4 days)||adults 50 mg twice/d (for 7 days)||adults 100 mg twice/d (for 7 days)' THEN 100 WHEN 'adults 20 mg' THEN 20 WHEN 'adults 500 mg||children 12 mg per 2' THEN 500 WHEN 'adults 500mcg||adults 250mcg' THEN 0.5 WHEN 'adults 20 mg||pediatric patients 0.5 mg/kg/dose or 1 mg/kg/dose' THEN 20 WHEN 'adults 1 mg norethindrone acetate and 10 mcg ethinyl estradiol per tablet' THEN 1 WHEN 'adults 500 mg' THEN 500 WHEN 'adults 12.5 mg (Day 1)||adults 12.5 mg twice daily (for 2 days)||adults 25 mg twice daily (for 4 days)||adults 50 mg twice daily (for 7 days)||adults 100 mg twice daily (for 7 days)' THEN 100 WHEN 'adults 25 mg || elderly 30-50 mg || adolescents 30-50 mg' THEN 25 WHEN 'children and adolescents up to 54mg daily||adults up to 72mg daily' THEN 72 WHEN 'adults 250 mg || adults 500 mg || adults 750 mg || adults 1000 mg' THEN 1000 WHEN 'adults 600 mg' THEN 600 WHEN 'adults 1-2 tablets 500mg||adults 1 tablet 750mg||children 1 drop/kg (not exceeding 35 drops)||children see weight-based mL dosing' THEN 1000 WHEN 'adults 1 mg || adults 2 mg' THEN 2 WHEN '15 mg' THEN 15 WHEN 'adults 25-50 mg' THEN 50 WHEN 'adults sinusitis 500 mg||adults acute exacerbation of c