mg||oral 800mg' THEN 800 WHEN 'adults 25 mg (oral capsule)||adults 1 mg (intravenous)||adults 10-20 mg (oral, equivalent to 1 mg IV)' THEN 25 WHEN 'patients with severe asthma aged 12 years and older 100 mg || adult patients with EGPA 3x100 mg' THEN 300 WHEN 'adults and adolescents (12 years and older) initial 400 mg (two 200 mg injections) || adults and adolescents (12 years and older) initial 600 mg (two 300 mg injections) || adults initial 600 mg (two 300 mg injections) || pediatric patients 15 to <30 kg 600 mg (two 300 mg injections) || pediatric patients 30 to <60 kg 400 mg (two 200 mg injections) || pediatric patients 60 kg or more 600 mg (two 300 mg injections)' THEN 600 ELSE NULL END AS mg, prescription_status FROM drug) WHERE mg IS NOT NULL GROUP BY dose_range;

-- G5b: For prescription-only drugs and the others, how many drug labels state a single dose, and how many of them give a dose per kilogram of body weight?
SELECT CASE WHEN prescription_status = 'prescription_only' THEN 'prescription only' ELSE 'other' END AS status, COUNT(*) AS drugs, SUM(CASE WHEN single_dose LIKE '%/kg%' THEN 1 ELSE 0 END) AS per_kg FROM drug WHERE single_dose <> '' GROUP BY status;
