onditions' WHEN 'pregnant women || women planning to become pregnant || breastfeeding women || patients with severe liver disease || patients with severe kidney disease || patients with high triglycerides || patients allergic to retinoids' THEN 'pregnancy||breastfeeding||kidney problems||liver problems||other conditions' WHEN 'patients with severe bradycardia||heart block greater than first degree||patients with cardiogenic shock||decompensated cardiac failure||sick sinus syndrome (unless a permanent pacemaker is in place)||patients with severe hepatic impairment (Child-Pugh greater than B)||hypersensitive to any component of this product||children under 18' THEN 'children||liver problems||other conditions' WHEN 'pregnant women||breastfeeding women||children' THEN 'pregnancy||breastfeeding||children' WHEN 'Women using oral contraceptives' THEN 'other conditions' WHEN 'patients taking nitrate containing medicines for cardiac insufficiency||patients with heart failure II stage||angina||complex forms of arrhythmias||resistant hypertension||states associated with a drop in blood pressure' THEN 'other conditions' WHEN 'men||postmenopausal women||children||patients with hepatic impairment||patients using alcohol||patients using moderate or strong CYP3A4 inhibitors||patients with hypersensitivity to Flibanserin or any inactive ingredient' THEN 'children||liver problems||other conditions' WHEN 'Allergic to Valium or other benzodiazepines||Pregnant women||Nursing mothers||Older adults' THEN 'pregnancy||breastfeeding||elderly||other conditions' WHEN 'people with individual intolerance of the active or additional elements of the drug||children younger than two months (ointment)||children under one year (cream)||people of old age (cautiously)||people with severe kidney dysfunction (cautiously)' THEN 'children||elderly||kidney problems||other conditions' WHEN 'patients allergic to Clarithromycin or other macrolide antibiotics||patients using Ergotamine, Dihydroergotamine, or oth